        public void FillEqualsMask(
            IHolotapeGetter item,
            IHolotapeGetter rhs,
            Holotape.Mask<bool> ret,
            EqualsMaskHelper.Include include = EqualsMaskHelper.Include.All)
        {
            ret.EDID = string.Equals(item.EDID, rhs.EDID);
            ret.ObjectBounds = MaskItemExt.Factory(item.ObjectBounds.GetEqualsMask(rhs.ObjectBounds, include), include);
            ret.PreviewTransform = item.PreviewTransform.Equals(rhs.PreviewTransform);
            ret.SnapTemplate = item.SnapTemplate.Equals(rhs.SnapTemplate);
            ret.XALG = MemorySliceExt.SequenceEqual(item.XALG, rhs.XALG);
            ret.FULL = object.Equals(item.FULL, rhs.FULL);
            ret.Model = EqualsMaskHelper.EqualsHelper(
                item.Model,
                rhs.Model,
                (loqLhs, loqRhs, incl) => loqLhs.GetEqualsMask(loqRhs, incl),
                include);
            ret.ICON = string.Equals(item.ICON, rhs.ICON);
            ret.PickUpSound = item.PickUpSound.Equals(rhs.PickUpSound);
            ret.PutDownSound = item.PutDownSound.Equals(rhs.PutDownSound);
            ret.Keywords = item.Keywords.CollectionEqualsHelper(
                rhs.Keywords,
                (l, r) => object.Equals(l, r),
                include);
            ret.ValueCurrency = item.ValueCurrency.Equals(rhs.ValueCurrency);
            ret.DNAM = item.DNAM == rhs.DNAM;
            ret.SNAM = item.SNAM.EqualsWithin(rhs.SNAM);
            ret.Quest = item.Quest.Equals(rhs.Quest);
            ret.PNAM = string.Equals(item.PNAM, rhs.PNAM);
            ret.Data = EqualsMaskHelper.EqualsHelper(
                item.Data,
                rhs.Data,
                (loqLhs, loqRhs, incl) => loqLhs.GetEqualsMask(loqRhs, incl),
                include);
            ret.VMAD = MemorySliceExt.SequenceEqual(item.VMAD, rhs.VMAD);
            base.FillEqualsMask(item, rhs, ret, include);
        }
        
